import { Entity, Index, ManyToOne, PrimaryKey, Property } from '@mikro-orm/decorators/legacy';
import type { Session } from '../../modules/sessions/session.js';
import { UserEntity } from './user.entity.js';

@Entity({ tableName: 'sessions' })
// By user for listing and revoking; by expiry for the daily purge.
@Index({ name: 'sessions_user_id_index', properties: ['userId'] })
@Index({ name: 'sessions_expires_at_index', properties: ['expiresAt'] })
export class SessionEntity implements Session {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryKey({ type: 'uuid' })
  id!: string;

  /** The user's id (`mapToPk`), not the user entity. */
  @ManyToOne(() => UserEntity, {
    mapToPk: true,
    fieldName: 'user_id',
    deleteRule: 'cascade',
    foreignKeyName: 'sessions_user_id_users_id_fk',
  })
  userId!: string;

  @Property({ type: 'text', nullable: true })
  userAgent!: string | null;

  @Property({ type: 'text', nullable: true })
  ip!: string | null;

  @Property({ type: 'datetime' })
  createdAt!: Date;

  @Property({ type: 'datetime' })
  lastUsedAt!: Date;

  @Property({ type: 'datetime' })
  expiresAt!: Date;

  @Property({ type: 'datetime' })
  absoluteExpiresAt!: Date;

  @Property({ type: 'datetime', nullable: true })
  revokedAt!: Date | null;
}
